internal sealed record DependencyInfo(string Feature,string Component,string Version,string Location,string Source,string Notes)
{
 public string Status=>Location=="External"?"Configure separately":Location=="Online"?"Optional internet map" : Location=="Windows"?"Windows component":Location=="Embedded"?"Embedded":File.Exists(FullPath)||Directory.Exists(FullPath)?"Present":"Missing / not installed";
 public string FullPath=>Path.IsPathRooted(Location)?Location:Path.Combine(AppContext.BaseDirectory,Location);
}
